const BY_ID = new Map(HUB_ICONS.map(i => [i.id, i]));

/**
 * Élément SVG d'une icône de la liste. Un identifiant inconnu (ancienne icône Grist, par exemple)
 * donne l'icône `fallback` : seul le contenu fixe de HUB_ICONS est inséré dans la page.
 */
export function hubIcon(id: string | undefined, fallback: string): SVGSVGElement {
  const found = BY_ID.get(id || "") || BY_ID.get(fallback) || HUB_ICONS[0];
  const holder = document.createElement("div");
  holder.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
    'stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + found.svg + "</svg>";
  return holder.firstChild as SVGSVGElement;
}
